from plotext._system import platform, memorize

space = ' '
default_marker = "hd" if platform == 'unix' else 'dot'

def check_marker(self, marker = None):
   marker = None if marker is None else str(marker)
   marker = default_marker if marker is None else marker
   #marker = ut.marker_codes[marker] if marker in marker_codes else marker
   #marker = marker if marker in hd_symbols else marker[0]
   return marker

class tick_class:
   def __init__(self):
      self.h = self.horizontal = '─'
      self.v = self.vertical =  '│'
      
      self.c = self.cross = '┼'
      self.r = self.right = '├'
      self.l = self.left  = '┤'
      self.u = self.upper = '┴'
      self.d = self.lower = '┬'
      self.ul = self.upper_left = '└'
      self.ur = self.upper_right = '┘'
      self.dl = self.lower_left = '┌'
      self.dr = self.lower_right = '┐'
      
      self.set_codes()
      self.set_markers()

   def set_codes(self): # clockwise 
      self.codes = {
         self.h: (1, 0, 1, 0),
         self.v: (0, 1, 0, 1),
         self.c: (1, 1, 1, 1),
         self.r: (0, 1, 1, 1),
         self.l: (1, 1, 0, 1),
         self.u: (1, 1, 1, 0),
         self.d: (1, 0, 1, 1),
         self.ul: (0, 1, 1, 0),
         self.ur: (1, 1, 0, 0),
         self.dl: (0, 0, 1, 1),
         self.dr: (1, 0, 0, 1)}

   def set_markers(self):
      self.markers = list(self.codes.keys())
      
   def sum(self, t1, t2):
      c1 = self.codes[t1] if t1 in self.codes else (0, 0, 0, 0)
      c2 = self.codes[t2] if t2 in self.codes else (0, 0, 0, 0)
      c = tuples_sum(c1, c2)
      return [k for k in self.codes.keys() if self.codes[k] == c][0]

tick = tick_class()

def sum_markers(old, new):
   if new == space:
      return old
   elif old in tick.markers and new in tick.markers:
       return tick.sum(old, new)
   else:
      return new



